import { z } from "zod";
const zCodeWidgetProps = z.object({
    code: z.string(),
    label: z.string().optional(),
    language: z.enum([
        "jsx",
        "javascript",
        "typescript",
        "sql",
        "bash",
        "json",
        "diff",
        "markdown",
        "python",
    ]),
    showLines: z.boolean().default(true),
    wrap: z.boolean().optional(),
    size: z.enum(["s", "m", "l", "stretch", "rows"]).optional(),
});
export function CodeWidget(define) {
    return define("Code")
        .props(zCodeWidgetProps)
        .render((props) => ({
        id: props.id,
        label: props.label,
        code: props.code,
        language: props.language,
        showLines: props.showLines,
        wrap: props.wrap,
        size: props.size,
    }));
}
